import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../App';

const navGroups = [
  {
    label: 'Core',
    items: [
      { path: '/dashboard', icon: '⊞', label: 'Dashboard' },
      { path: '/agents', icon: '🧠', label: 'AI Agents' },
    ]
  },
  {
    label: 'Intelligence',
    items: [
      { path: '/recommendations', icon: '🌱', label: 'Crop Prediction' },
      { path: '/market', icon: '📈', label: 'Market Trends' },
      { path: '/disease-scanner', icon: '🔬', label: 'Disease Scanner' },
    ]
  },
  {
    label: 'Farm Management',
    items: [
      { path: '/weather', icon: '🌤', label: 'Weather Alerts' },
      { path: '/water', icon: '💧', label: 'Water Management' },
      { path: '/fertilizer', icon: '🧪', label: 'Fertilizer Guide' },
      { path: '/sustainability', icon: '♻️', label: 'Sustainability' },
    ]
  },
  {
    label: 'Assistant',
    items: [
      { path: '/chatbot', icon: '🤖', label: 'KisanGPT Voice' },
    ]
  }
];

export default function Sidebar({ open, onClose }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, setUser, lang, setLang, LANGS, darkMode, setDarkMode } = useAuth();

  const go = (path) => { navigate(path); onClose?.(); };

  return (
    <>
      {open && <div className="fixed inset-0 bg-black/60 z-30 lg:hidden" onClick={onClose} />}
      <aside className={`fixed top-0 left-0 h-full w-64 z-40 flex flex-col glass-dark border-r border-green-900/40 transition-transform duration-300 ${open ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
        {/* Logo */}
        <div className="p-5 border-b border-green-900/40">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-xl btn-primary flex items-center justify-center text-lg ai-glow">🌿</div>
              <div>
                <div className="font-display font-bold text-white text-base leading-tight">SmartSheti</div>
                <div className="text-green-400 text-xs font-medium tracking-widest">AI PLATFORM</div>
              </div>
            </div>
            <button onClick={() => setDarkMode(d => !d)}
              className="w-8 h-8 glass rounded-lg flex items-center justify-center text-sm hover:bg-green-900/20 transition-all" title="Toggle theme">
              {darkMode ? '☀️' : '🌙'}
            </button>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 p-3 overflow-y-auto space-y-4">
          {navGroups.map(group => (
            <div key={group.label}>
              <div className="text-gray-600 text-xs uppercase tracking-widest px-3 mb-1">{group.label}</div>
              {group.items.map(item => (
                <button key={item.path} onClick={() => go(item.path)}
                  className={`sidebar-link w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-left text-sm font-medium transition-all ${location.pathname === item.path ? 'active bg-green-500/20 text-green-300 border-l-4 border-green-400' : 'text-gray-400 hover:text-white'}`}>
                  <span className="text-base w-5 text-center">{item.icon}</span>
                  {item.label}
                </button>
              ))}
            </div>
          ))}
        </nav>

        {/* Language */}
        <div className="px-4 pb-2 border-t border-green-900/40 pt-3">
          <div className="text-xs text-gray-500 mb-1.5 uppercase tracking-wider">Language</div>
          <div className="flex items-center gap-2">
            <select
              value={lang}
              onChange={e => setLang(e.target.value)}
              className="flex-1 bg-black/30 border border-green-900/40 text-white text-xs rounded-lg px-3 py-2"
            >
              {LANG_LIST.map(l => (
                <option key={l.code} value={l.code}>{l.flag} {l.native}</option>
              ))}
            </select>
            <button
              onClick={() => go('/select-language')}
              className="w-8 h-8 glass rounded-lg flex items-center justify-center text-sm hover:bg-green-900/20 transition-all flex-shrink-0"
              title="Change language"
            >
              🌐
            </button>
          </div>
        </div>

        {/* User */}
        <div className="p-4 border-t border-green-900/40">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-green-400 to-green-700 flex items-center justify-center text-white font-bold text-sm flex-shrink-0">
              {user?.name?.[0]?.toUpperCase() || 'F'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-white text-sm font-medium truncate">{user?.name || 'Farmer'}</div>
              <div className="text-gray-500 text-xs truncate">{user?.state || 'India'} · {user?.acres || '5'} acres</div>
            </div>
            <button onClick={() => setUser(null)} className="text-gray-500 hover:text-red-400 text-sm transition-colors" title="Logout">⏻</button>
          </div>
        </div>
      </aside>
    </>
  );
}
